SELECT  FROM project_version
WHERE workspace_id = #{workspaceId} AND req_id = #{reqId}
ORDER BY FIELD(status, 'active', 'planned', 'released'), created_at DESC, id

SELECT  FROM project_version
WHERE workspace_id = #{workspaceId}
ORDER BY created_at, id

SELECT req_id AS reqId, COUNT(*) AS cnt
FROM project_version WHERE workspace_id = #{workspaceId}
GROUP BY req_id

SELECT COUNT(*) FROM project_version
WHERE workspace_id = #{workspaceId} AND req_id = #{reqId} AND name = #{name}
AND id <> #{excludeId}
